export const getInventoryHistoryUrl = (params?: { storeId?: number; chemicalId?: number; limit?: number }) => {
  const query = new URLSearchParams();
  if (params?.storeId !== undefined) query.set('storeId', String(params.storeId));
  if (params?.chemicalId !== undefined) query.set('chemicalId', String(params.chemicalId));
  if (params?.limit !== undefined) query.set('limit', String(params.limit));
  const qs = query.toString();
  return `/api/inventory/history${qs ? `?${qs}` : ''}`;
}

